/**
 * World map geometry for the about page travel section.
 *
 * Source: Natural Earth 1:50m admin-0 boundaries (public domain), projected
 * with the Miller cylindrical projection on the Greenwich meridian and
 * simplified with Douglas-Peucker to integer viewBox units. Cylindrical keeps
 * meridians vertical, so land reaches the full canvas width at every latitude
 * and fragments crossing the antimeridian sit flush against the edges.
 *
 * Antarctica is omitted. Each country keeps its largest ring no matter how
 * small, so no state disappears; only outlying specks are trimmed.
 *
 * One path per country, so highlighting is a matter of listing ISO codes - see
 * `countryRelations` in `src/data/travel.ts`.
 */

export const WORLD_MAP_WIDTH = 1000;
export const WORLD_MAP_HEIGHT = 501;

/* Miller cylindrical, and the fit of its output onto the viewBox above. */
const PROJECTED_MIN_X = -Math.PI;
const PROJECTED_MIN_Y = -1.983703475378;
const PROJECTED_SCALE = 159.154943092;

/** Places geographic coordinates on the map as percentages of its box. */
export function projectWorldToPercent(latitude: number, longitude: number) {
  const x = (longitude * Math.PI) / 180;
  const y =
    -1.25 *
    Math.log(Math.tan(Math.PI / 4 + 0.4 * ((latitude * Math.PI) / 180)));

  return {
    left: ((x - PROJECTED_MIN_X) * PROJECTED_SCALE * 100) / WORLD_MAP_WIDTH,
    top: ((y - PROJECTED_MIN_Y) * PROJECTED_SCALE * 100) / WORLD_MAP_HEIGHT,
  };
}

export interface PathBounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * Bounding box of a country path in viewBox units, used to size an image laid
 * over that country (see the flag fills on the world map).
 */
export function getPathBounds(path: string): PathBounds {
  const points = Array.from(
    path.matchAll(/[ML](-?[\d.]+) (-?[\d.]+)/g),
    (match) => [Number.parseFloat(match[1]), Number.parseFloat(match[2])],
  );
  const xs = points.map(([x]) => x);
  const ys = points.map(([, y]) => y);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);

  return {
    x: minX,
    y: minY,
    width: Math.max(...xs) - minX,
    height: Math.max(...ys) - minY,
  };
}

